int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    const char *pair_start = in;
    int pair_count = 0;

    while (pair_count < max_pairs) {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;
        size_t klen = (size_t)(eq - pair_start);
        keys_out[pair_count] = malloc(klen + 1);
        strncpy(keys_out[pair_count], pair_start, klen);
        keys_out[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') ++val_start;

        if (*val_start == '"') {
            const char *end_quote = strchr(val_start + 1, '"');
            if (!end_quote) break;
            size_t vlen = (size_t)(end_quote - val_start - 1);
            vals_out[pair_count] = malloc(vlen + 1);
            strncpy(vals_out[pair_count], val_start + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
            pair_start = end_quote + 2;
        } else {
            const char *end_val = strchr(val_start, ' ');
            if (!end_val) end_val = in + strlen(in);
            size_t vlen = (size_t)(end_val - val_start);
            vals_out[pair_count] = malloc(vlen + 1);
            strncpy(vals_out[pair_count], val_start, vlen);
            vals_out[pair_count][vlen] = '\0';
            pair_start = end_val;
        }

        ++pair_count;
    }

    return pair_count;
}

